  // Format number with commas
  function formatNumber(num) {
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    if (num >= 1e3) return num.toLocaleString('en-US', { maximumFractionDigits: 2 });
    return num.toFixed(2);
  }

  // Format price
  function formatPrice(price) {
    if (price >= 1000) return '$' + price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    if (price >= 1) return '$' + price.toFixed(2);
    return '$' + price.toFixed(6);
  }

  // Generate sparkline bars
  function generateSparkline(data) {
    const max = Math.max(...data);
    const min = Math.min(...data);
    const last = data[data.length - 1];
    const first = data[0];
    const trend = last >= first ? 'up' : 'down';

    return data.map(val => {
      const height = ((val - min) / (max - min)) * 20 + 4;
      return `<div class="sparkline-bar ${trend}" style="height:${height}px"></div>`;
    }).join('');
  }

  // Render table
  function renderTable(data) {
    const tbody = document.getElementById('cryptoTableBody');
    tbody.innerHTML = data.map(coin => `
      <tr>
        <td class="right rank">${coin.rank}</td>
        <td>
          <div class="coin-info">
            <div class="coin-icon">${coin.symbol.charAt(0)}</div>
            <div>
              <div class="coin-name">${coin.name}</div>
              <div class="coin-symbol">${coin.symbol}</div>
            </div>
          </div>
        </td>
        <td class="right price">${formatPrice(coin.price)}</td>
        <td class="right change ${coin.change1h >= 0 ? 'positive' : 'negative'}" style="color: var(--${coin.change1h >= 0 ? 'positive' : 'negative'})">${coin.change1h >= 0 ? '+' : ''}${coin.change1h.toFixed(2)}%</td>
        <td class="right change" style="color: var(--${coin.change24h >= 0 ? 'positive' : 'negative'})">${coin.change24h >= 0 ? '+' : ''}${coin.change24h.toFixed(2)}%</td>
        <td class="right change" style="color: var(--${coin.change7d >= 0 ? 'positive' : 'negative'})">${coin.change7d >= 0 ? '+' : ''}${coin.change7d.toFixed(2)}%</td>
        <td class="right">$${formatNumber(coin.marketCap)}</td>
        <td class="right">$${formatNumber(coin.volume)}</td>
        <td class="right">${coin.supply}</td>
        <td><div class="sparkline">${generateSparkline(coin.sparkline)}</div></td>
      </tr>
    `).join('');
  }

  // Toggle dropdown
  function toggleDropdown(id) {
    const dropdown = document.getElementById(id);
    const isOpen = dropdown.classList.contains('show');
    document.querySelectorAll('.dropdown-panel').forEach(d => d.classList.remove('show'));
    if (!isOpen) dropdown.classList.add('show');
  }

  // Toggle market summary
  function toggleMarketSummary() {
    const extra = document.getElementById('marketSummaryExtra');
    const btn = document.querySelector('.read-more-btn');
    extra.classList.toggle('show');
    btn.textContent = extra.classList.contains('show') ? 'Show Less ▲' : 'Read More ▾';
  }

  // Tab interactions
  document.querySelectorAll('.tab').forEach(tab => {
    tab.addEventListener('click', function() {
      document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      this.classList.add('active');
    });
  });

  document.querySelectorAll('.category-tab').forEach(tab => {
    tab.addEventListener('click', function() {
      document.querySelectorAll('.category-tab').forEach(t => t.classList.remove('active'));
      this.classList.add('active');
    });
  });

  // Pagination
  document.querySelectorAll('.page-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      if (this.textContent === '...' || this.disabled) return;
      document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
      this.classList.add('active');
    });
  });

  // Close dropdowns when clicking outside
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.table-actions')) {
      document.querySelectorAll('.dropdown-panel').forEach(d => d.classList.remove('show'));
    }
  });

  // Column visibility toggle
  document.querySelectorAll('#columnsDropdown input').forEach(input => {
    input.addEventListener('change', function() {
      const col = this.dataset.col;
      const cells = document.querySelectorAll(`td:nth-child(${getColumnIndex(col)}), th:nth-child(${getColumnIndex(col)})`);
      cells.forEach(cell => {
        cell.style.display = this.checked ? '' : 'none';
      });
    });
  });

  function getColumnIndex(col) {
    const cols = ['rank', 'name', 'price', '1h', '24h', '7d', 'marketCap', 'volume', 'supply', 'sparkline'];
    return cols.indexOf(col) + 1;
  }

  // Initialize
  renderTable(cryptoData);
</script>

